/// The unchanged ledger has no table column. Positive result versions denote
/// objects; zero denotes an unversioned append result, whose id identifies its
/// log/xref kind. Negative versions denote candidate-state results (the negated
/// candidate version). Keys remain global per Device, never scoped to this enum.
#[derive(Clone, Copy)]
pub(crate) enum MutationTarget {
    Object,
    Log,
    ExternalReference,
    Candidate,
}

impl MutationTarget {
    fn table(self) -> &'static str {
        match self {
            Self::Object => "objects",
            Self::Log => "logs",
            Self::ExternalReference => "external_references",
            Self::Candidate => "advisory_candidates",
        }
    }

    fn accepts(self, recorded: &RecordedMutation) -> bool {
        match self {
            Self::Object => recorded.result_version > 0,
            Self::Candidate => {
                recorded.result_version < 0
                    && ubu_core::AdvisoryCandidateId::parse(&recorded.result_object_id).is_ok()
            }
            Self::Log | Self::ExternalReference => {
                let expected = match self {
                    Self::Log => ObjectType::LogEntry,
                    _ => ObjectType::ExternalReference,
                };
                recorded.result_version == 0
                    && UbuId::parse(&recorded.result_object_id)
                        .and_then(|id| id.require_object_type(expected))
                        .is_ok()
            }
        }
    }
}

pub(crate) struct PreparedMutation {
    pub(crate) canonical_payload: String,
    pub(crate) replay: Option<RecordedMutation>,
}

/// Validate and check the shared device-scoped ledger before any preconditions.
/// Payload equality is unchanged for admit_object and applies to record.payload
/// for append-only writers. A same-payload key cannot switch result tables.
pub(crate) async fn prepare_mutation(
    connection: &mut SqliteConnection,
    envelope: &MutationEnvelope,
    payload: &Value,
    target: MutationTarget,
) -> Result<PreparedMutation> {
    envelope.validate()?;
    let key = envelope.mutation_key();
    let canonical_payload = String::from_utf8(canonical_payload_bytes(payload))
        .expect("canonical JSON bytes are UTF-8");
    let replay = lookup_mutation(&mut *connection, &key).await?;
    if let Some(recorded) = &replay {
        if recorded.canonical_payload != canonical_payload {
            return Err(ubu_core::UbuError::IdempotencyKeyConflict {
                origin_device_id: key.origin_device_id.as_str().to_owned(),
                idempotency_key: key.idempotency_key.as_str().to_owned(),
            }
            .into());
        }
        if !target.accepts(recorded) {
            return Err(StoreError::ReplayTargetMismatch {
                object_id: recorded.result_object_id.clone(),
                expected_table: target.table(),
            });
        }
    } else {
        check_preconditions(connection, envelope).await?;
    }
    Ok(PreparedMutation {
        canonical_payload,
        replay,
    })
}

async fn check_preconditions(
    connection: &mut SqliteConnection,
    envelope: &MutationEnvelope,
) -> Result<()> {
    for (object_id, expected) in &envelope.observed_versions {
        let actual: Option<i64> = sqlx::query_scalar("SELECT version FROM objects WHERE id = ?")
            .bind(object_id.as_str())
            .fetch_optional(&mut *connection)
            .await?;
        let matches = match (expected, actual) {
            (VersionRef::Absent, None) => true,
            (VersionRef::Version(expected), Some(actual)) => {
                u64::try_from(actual).ok() == Some(*expected)
            }
            _ => false,
        };
        if !matches {
            return Err(StoreError::PreconditionFailed {
                object_id: object_id.as_str().to_owned(),
                expected: match expected {
                    VersionRef::Absent => "absent".to_owned(),
                    VersionRef::Version(version) => format!("v{version}"),
                },
                actual: actual.map_or_else(|| "absent".to_owned(), |version| format!("v{version}")),
            });
        }
    }
    Ok(())
}

pub(crate) async fn record_mutation(
    connection: &mut SqliteConnection,
    envelope: &MutationEnvelope,
    canonical_payload: &str,
    object_id: &str,
    version: i64,
) -> Result<()> {
    sqlx::query(
        "INSERT INTO mutation_envelopes
         (origin_device_id, idempotency_key, envelope_json, canonical_payload,
          result_object_id, result_version, recorded_at)
         VALUES (?, ?, ?, ?, ?, ?, ?)",
    )
    .bind(envelope.origin_device_id.as_str())
    .bind(envelope.idempotency_key.as_str())
    .bind(serde_json::to_string(envelope)?)
    .bind(canonical_payload)
    .bind(object_id)
    .bind(version)
    .bind(envelope.recorded_time.to_string())
    .execute(connection)
    .await?;
    Ok(())
}

pub(crate) async fn finish_mutation<T>(
    transaction: Transaction<'_, Sqlite>,
    result: Result<T>,
) -> Result<T> {
    match result {
        Ok(record) => {
            transaction.commit().await?;
            Ok(record)
        }
        Err(error) => {
            transaction.rollback().await?;
            Err(error)
        }
    }
}

fn target_precondition(envelope: &MutationEnvelope, id: &UbuId) -> Result<VersionRef> {
    envelope.observed_versions.get(id).copied().ok_or_else(|| {
        StoreError::MissingTargetPrecondition {
            object_id: id.to_string(),
        }
    })
}

async fn read_object_result(
    connection: &mut SqliteConnection,
    object_id: &str,
) -> Result<ObjectRecord> {
    get_current_state(connection, object_id)
        .await?
        .ok_or_else(|| StoreError::RecordedMutationObjectMissing {
            object_id: object_id.to_owned(),
        })
}

/// Private shared object writer, reachable only after envelope checks on the
/// same transaction. Preserve existing record validation and created_at on updates.
async fn write_object_row(
    connection: &mut SqliteConnection,
    envelope: &MutationEnvelope,
    mut record: NewObjectRecord,
) -> Result<ObjectRecord> {
    let expected = target_precondition(envelope, &UbuId::parse(&record.id)?)?;
    validate_object_record(&record)?;
    if record.object_type == "Task" {
        if let Some(key) = record
            .payload
            .pointer("/occurrence/key")
            .and_then(serde_json::Value::as_str)
        {
            let held: bool = sqlx::query_scalar("SELECT EXISTS(SELECT 1 FROM objects WHERE object_type = 'Task' AND json_extract(payload_json, '$.occurrence.key') = ? AND id <> ?)")
                .bind(key).bind(&record.id).fetch_one(&mut *connection).await?;
            if held {
                return Err(StoreError::DuplicateOccurrenceKey {
                    key: key.to_owned(),
                });
            }
        }
    }
    let payload_json = serde_json::to_string(&record.payload)?;
    match expected {
        VersionRef::Absent => {
            record.version = 1;
            sqlx::query(
                "INSERT INTO objects
                 (id, object_type, version, status, compartment_label, payload_json, created_at, updated_at)
                 VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
            )
            .bind(&record.id)
            .bind(&record.object_type)
            .bind(record.version)
            .bind(&record.status)
            .bind(&record.compartment_label)
            .bind(&payload_json)
            .bind(&record.created_at)
            .bind(&record.updated_at)
            .execute(&mut *connection)
            .await?;
        }
        VersionRef::Version(version) => {
            record.version = i64::try_from(version)
                .ok()
                .and_then(|v| v.checked_add(1))
                .ok_or_else(|| StoreError::ObjectVersionExhausted {
                    object_id: record.id.clone(),
                    version,
                })?;
            sqlx::query(
                "UPDATE objects SET version = ?, status = ?, compartment_label = ?,
                 payload_json = ?, updated_at = ? WHERE id = ?",
            )
            .bind(record.version)
            .bind(&record.status)
            .bind(&record.compartment_label)
            .bind(&payload_json)
            .bind(&record.updated_at)
            .bind(&record.id)
            .execute(&mut *connection)
            .await?;
        }
    }
    read_object_result(connection, &record.id).await
}

/// Admit one canonical object mutation atomically with its envelope.
/// Device registration/trust and policy-version enforcement belong to later tickets.
/// Replay equality is deliberately defined over `record.payload` alone. A replay
/// reads the recorded target's current state; the ledger is not historical state.
pub async fn admit_object(
    pool: &SqlitePool,
    envelope: &MutationEnvelope,
    record: NewObjectRecord,
) -> Result<ObjectRecord> {
    let mut transaction = crate::transactions::begin(pool).await?;
    let result = async {
        let prepared = prepare_mutation(
            &mut transaction,
            envelope,
            &record.payload,
            MutationTarget::Object,
        )
        .await?;
        admit_prepared_object(&mut transaction, envelope, record, prepared).await
    }
    .await;
    finish_mutation(transaction, result).await
}

/// Complete ordinary object admission on an already prepared transaction.
/// Candidate admission composes this exact path with its candidate/event writes;
/// only the outer public writer owns commit or rollback.
pub(crate) async fn admit_prepared_object(
    connection: &mut SqliteConnection,
    envelope: &MutationEnvelope,
    record: NewObjectRecord,
    prepared: PreparedMutation,
) -> Result<ObjectRecord> {
    if let Some(replay) = prepared.replay {
        return read_object_result(connection, &replay.result_object_id).await;
    }
    let admitted = write_object_row(connection, envelope, record).await?;
    record_mutation(
        connection,
        envelope,
        &prepared.canonical_payload,
        &admitted.id,
        admitted.version,
    )
    .await?;
    Ok(admitted)
}

/// Append a canonical fact. The log id needs no object-version precondition;
/// all supplied read preconditions are enforced. Replay compares record.payload.
pub async fn append_log_entry(
    pool: &SqlitePool,
    envelope: &MutationEnvelope,
    record: NewLogRecord,
) -> Result<LogRecord> {
    let mut transaction = crate::transactions::begin(pool).await?;
    let result = async {
        let prepared = prepare_mutation(
            &mut transaction,
            envelope,
            &record.payload,
            MutationTarget::Log,
        )
        .await?;
        append_prepared_log(&mut transaction, envelope, record, prepared).await
    }
    .await;
    finish_mutation(transaction, result).await
}

/// Complete Log admission on the transaction owned by the outer writer.
pub(crate) async fn append_prepared_log(
    connection: &mut SqliteConnection,
    envelope: &MutationEnvelope,
    record: NewLogRecord,
    prepared: PreparedMutation,
) -> Result<LogRecord> {
    if let Some(replay) = prepared.replay {
        return sqlx::query_as::<_, LogRecord>("SELECT * FROM logs WHERE id = ?")
            .bind(replay.result_object_id)
            .fetch_one(&mut *connection)
            .await
            .map_err(Into::into);
    }
    validate_object_id_for_type(&record.id, ObjectType::LogEntry.as_str())?;
    validate_provenance_json(&record.provenance)?;
    if record.event_type == "recalculation_requested" {
        validate_recalculation_trigger_payload(&record.payload)?;
    }
    UbuTimestamp::parse(&record.created_at)?;
    let object_refs_json = serde_json::to_string(&record.object_refs)?;
    let payload_json = serde_json::to_string(&record.payload)?;
    let provenance_json = serde_json::to_string(&record.provenance)?;

    sqlx::query(
        "INSERT INTO logs
    (id, event_type, object_refs_json, payload_json, provenance_json, created_at)
    VALUES (?, ?, ?, ?, ?, ?)",
    )
    .bind(&record.id)
    .bind(&record.event_type)
    .bind(&object_refs_json)
    .bind(&payload_json)
    .bind(&provenance_json)
    .bind(&record.created_at)
    .execute(&mut *connection)
    .await?;

    record_mutation(
        connection,
        envelope,
        &prepared.canonical_payload,
        &record.id,
        0,
    )
    .await?;

    sqlx::query_as::<_, LogRecord>("SELECT * FROM logs WHERE id = ?")
        .bind(&record.id)
        .fetch_one(&mut *connection)
        .await
        .map_err(Into::into)
}

/// One canonical write inside a batch. Each write carries its own envelope:
/// the ledger is keyed by `(origin_device_id, idempotency_key)` and one key
/// records exactly one result object.
#[derive(Debug, Clone)]
pub enum BatchWrite {
    Object {
        envelope: MutationEnvelope,
        record: NewObjectRecord,
    },
    Log {
        envelope: MutationEnvelope,
        record: NewLogRecord,
    },
}

/// The admitted result of one `BatchWrite`, in request order.
#[derive(Debug, Clone)]
pub enum BatchResult {
    Object(ObjectRecord),
    Log(LogRecord),
}

impl BatchResult {
    pub fn as_object(&self) -> Option<&ObjectRecord> {
        match self {
            Self::Object(record) => Some(record),
            Self::Log(_) => None,
        }
    }
    pub fn as_log(&self) -> Option<&LogRecord> {
        match self {
            Self::Log(record) => Some(record),
            Self::Object(_) => None,
        }
    }
}

/// Atomically admit ordered canonical writes. Later preconditions observe
/// earlier writes. Replay retains the ordinary writers' current-state semantics.
/// Only this outer writer owns commit or rollback; no transaction escapes it.
pub async fn admit_batch(pool: &SqlitePool, writes: Vec<BatchWrite>) -> Result<Vec<BatchResult>> {
    let mut transaction = crate::transactions::begin(pool).await?;
    let result = async {
        let mut seen = std::collections::HashSet::new();
        let mut results = Vec::with_capacity(writes.len());
        for write in writes {
            let envelope = match &write {
                BatchWrite::Object { envelope, .. } | BatchWrite::Log { envelope, .. } => envelope,
            };
            // prepare_mutation intentionally permits same-payload replay. Within
            // one request, even identical repeated keys are a caller error.
            if !seen.insert(envelope.mutation_key()) {
                return Err(ubu_core::UbuError::IdempotencyKeyConflict {
                    origin_device_id: envelope.origin_device_id.as_str().to_owned(),
                    idempotency_key: envelope.idempotency_key.as_str().to_owned(),
                }
                .into());
            }
            results.push(match write {
                BatchWrite::Object { envelope, record } => {
                    let prepared = prepare_mutation(
                        &mut transaction,
                        &envelope,
                        &record.payload,
                        MutationTarget::Object,
                    )
                    .await?;
                    BatchResult::Object(
                        admit_prepared_object(&mut transaction, &envelope, record, prepared)
                            .await?,
                    )
                }
                BatchWrite::Log { envelope, record } => {
                    let prepared = prepare_mutation(
                        &mut transaction,
                        &envelope,
                        &record.payload,
                        MutationTarget::Log,
                    )
                    .await?;
                    BatchResult::Log(
                        append_prepared_log(&mut transaction, &envelope, record, prepared).await?,
                    )
                }
            });
        }
        Ok(results)
    }
    .await;
    finish_mutation(transaction, result).await
}

/// Canonical admission audit view. Candidate-only requests contain review data
/// and are excluded; the private replay lookup still sees all Device-global keys.
pub async fn get_recorded_mutation<'e, E>(
    executor: E,
    key: &MutationKey,
) -> Result<Option<RecordedMutation>>
where
    E: Executor<'e, Database = Sqlite>,
{
    Ok(lookup_mutation(executor, key)
        .await?
        .filter(|row| row.result_version >= 0))
}

async fn lookup_mutation<'e, E>(executor: E, key: &MutationKey) -> Result<Option<RecordedMutation>>
where
    E: Executor<'e, Database = Sqlite>,
{
    sqlx::query_as::<_, RecordedMutation>(
        "SELECT * FROM mutation_envelopes WHERE origin_device_id = ? AND idempotency_key = ?",
    )
    .bind(key.origin_device_id.as_str())
    .bind(key.idempotency_key.as_str())
    .fetch_optional(executor)
    .await
    .map_err(Into::into)
}

