        "SELECT * FROM objects WHERE object_type = ? AND status = ? ORDER BY updated_at DESC",
    )
    .bind(ObjectType::Task.as_str())
    .bind("active")
    .fetch_all(pool)
    .await
    .map_err(Into::into)
}

